SELECT m.id AS wmp_id, p.id AS paper_id, p.symbol, p.status, p.close_reason, p.entry_price, f.market_price_usdt AS first_ext_price, UNIX_TIMESTAMP(f.occurred_at) AS first_ext_epoch, ROUND((f.market_price_usdt-p.entry_price)/p.entry_price*100,4) AS first_ext_pct, ROUND((p.exit_price-p.entry_price)/p.entry_price*100,4) AS realized_pct, ROUND(p.quantity*(f.market_price_usdt-p.entry_price),6) AS cf_pnl, ROUND(p.realized_pnl,6) AS realized_pnl FROM crypto_ai.position_management_event f JOIN (SELECT wallet_position_id, MIN(id) AS first_id FROM crypto_ai.position_management_event WHERE event_type='TAKE_PROFIT_EXTENDED' AND occurred_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400) GROUP BY wallet_position_id) fe ON fe.first_id=f.id JOIN crypto_ai.wallet_managed_position m ON m.id=f.wallet_position_id JOIN crypto_ai.paper_position p ON p.signal_id=m.entry_signal_id WHERE p.status IN ('CLOSED','STOPPED') ORDER BY p.id LIMIT 100;